const response = $input.first().json;

const data = response.data?.vendor_product_variations;

if (!data || !Array.isArray(data.items)) {
  return [{
    json: {
      success: false,
      message: "ساختار پاسخ اسنپ‌مارکت معتبر نیست"
    }
  }];
}

const offers = [];

for (const store of data.items) {
  // فقط فروشگاه باز و قابل ارسال
  if (
    !store.is_open ||
    !store.deliver ||
    store.does_deliver === false
  ) continue;

  for (const product of (store.products || [])) {
    if (!product.stock || product.stock <= 0) continue;

    const price = Number(product.price || 0);
    const discount = Number(product.discount || 0);
    const finalPrice = price - discount;

    if (finalPrice <= 0) continue;

    offers.push({
      price: finalPrice,
      title: product.title
    });
  }
}

offers.sort((a, b) => a.price - b.price);

if (offers.length === 0) {
  return [{
    json: {
      success: false,
      message: "محصول موجودی پیدا نشد"
    }
  }];
}

return [{
  json: {
    success: true,
    price: offers[0].price
  }
}];
